type DataDiffColumn = {
  readonly id: string;
  readonly label: string;
};

type DataDiffOwnProps = {
  label: string;
  description?: string;
  columns: readonly DataDiffColumn[];
  rows: readonly DataDiffRow[];
  selectedIds?: readonly string[];
  defaultSelectedIds?: readonly string[];
  onSelectionChange?: (ids: readonly string[]) => void;
  onApply?: (ids: readonly string[]) => void;
  pending?: boolean;
  disabled?: boolean;
  applyLabel?: string;
  emptyMessage?: string;
};

type DataDiffProps = DataDiffOwnProps & Omit<React.HTMLAttributes<HTMLDivElement>, keyof DataDiffOwnProps | 'children' | 'dangerouslySetInnerHTML'> & {
  children?: never;
  dangerouslySetInnerHTML?: never;
};

type DataDiffRow = {
  readonly id: string;
  readonly label: string;
  readonly disabled?: boolean;
  readonly kind: 'unchanged' | 'added' | 'removed';
  readonly values: DataDiffValues;
  readonly before?: never;
  readonly after?: never;
} | {
  readonly id: string;
  readonly label: string;
  readonly disabled?: boolean;
  readonly kind: 'updated';
  readonly before: DataDiffValues;
  readonly after: DataDiffValues;
  readonly values?: never;
};

type DataDiffRowIdentity = {
  readonly id: string;
  readonly label: string;
  readonly disabled?: boolean;
};
